import XCTest

final class SettingsUITests: XCTestCase {
    func testOpenSettings() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        if app.state != .runningForeground {
            app.launch()
        }

        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        try? app.debugDescription.write(to: docs.appendingPathComponent("hierarchy_before.txt"), atomically: true, encoding: .utf8)

        let navButton = app.navigationBars.buttons.firstMatch
        if navButton.waitForExistence(timeout: 5) {
            navButton.tap()
        } else {
            app.coordinate(withNormalizedOffset: CGVector(dx: 0.07, dy: 0.07)).tap()
        }

        Thread.sleep(forTimeInterval: 3)
        try? app.debugDescription.write(to: docs.appendingPathComponent("hierarchy_after.txt"), atomically: true, encoding: .utf8)
    }
}

import XCTest

final class SettingsUITests: XCTestCase {
    func testOpenSettings() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        if app.state != .runningForeground {
            app.launch()
        }
        let userSettings = app.descendants(matching: .any)["User settings"].firstMatch
        XCTAssertTrue(userSettings.waitForExistence(timeout: 10))
