import XCTest

final class SettingsUITests: XCTestCase {
    func testOpenSettings() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        if app.state != .runningForeground {
            app.launch()
        }
        var userSettings = app.descendants(matching: .any)["User settings"].firstMatch
        if !userSettings.waitForExistence(timeout: 3) {
            let avatar = app.navigationBars.buttons.firstMatch
            XCTAssertTrue(avatar.waitForExistence(timeout: 5))
            avatar.tap()
            userSettings = app.descendants(matching: .any)["User settings"].firstMatch
            XCTAssertTrue(userSettings.waitForExistence(timeout: 5))
        }
        userSettings.tap()
        Thread.sleep(forTimeInterval: 2)
    }
}
